import{_ as t,o,c as r,ah as n}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"Wolfgang Hattmannsdorfer: The New Crown Prince of the OÖVP","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/wolfgang-hattmannsdorfer.md","filePath":"en/recherche/wolfgang-hattmannsdorfer.md"}'),a={name:"en/recherche/wolfgang-hattmannsdorfer.md"};function s(i,e,h,l,c,f){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="wolfgang-hattmannsdorfer-the-new-crown-prince-of-the-oovp" tabindex="-1">Wolfgang Hattmannsdorfer: The New Crown Prince of the OÖVP <a class="header-anchor" href="#wolfgang-hattmannsdorfer-the-new-crown-prince-of-the-oovp" aria-label="Permalink to &quot;Wolfgang Hattmannsdorfer: The New Crown Prince of the OÖVP&quot;">​</a></h1><p>With the resignation of August Wöginger on March 23, 2026, a figure steps into the spotlight who has previously acted more as a strategic mastermind in the background: <strong>Wolfgang Hattmannsdorfer</strong>. He is not only taking over Wöginger&#39;s post as deputy state party leader in Upper Austria but is also solidifying his claim to the future leadership of the state party.</p><h2 id="who-is-wolfgang-hattmannsdorfer" tabindex="-1">Who is Wolfgang Hattmannsdorfer? <a class="header-anchor" href="#who-is-wolfgang-hattmannsdorfer" aria-label="Permalink to &quot;Who is Wolfgang Hattmannsdorfer?&quot;">​</a></h2><p>Hattmannsdorfer (*1979 in Linz) is considered the &quot;political professional&quot; of the Upper Austrian People&#39;s Party (OÖVP). His career is marked by a rapid rise and a consistent networking between state and federal politics:</p><ol><li><strong>The Strategist:</strong> As state manager (2013–2021), he was the architect of the electoral successes of State Governor Thomas Stelzer. He knows the structures of power in Upper Austria like no other.</li><li><strong>The Hardliner:</strong> In his roles as state councilor for social affairs and integration, and later at the federal level, he often positioned himself with a hard line – especially on issues such as social assistance cuts and strict integration requirements.</li><li><strong>The Networker:</strong> His move as secretary general of the Chamber of Commerce (WKO) and later as Federal Minister for Economic Affairs shows his deep roots in the economic power centers of the country.</li></ol><h2 id="the-role-in-the-horten-mystery" tabindex="-1">The Role in the &quot;Horten Mystery&quot; <a class="header-anchor" href="#the-role-in-the-horten-mystery" aria-label="Permalink to &quot;The Role in the &quot;Horten Mystery&quot;&quot;">​</a></h2><p>For our forensic analysis, Hattmannsdorfer is a prime example of the <strong>&quot;Pointillism of Power&quot;</strong>. While Wöginger embodied the &quot;Hard Prose&quot; of direct patronage, Hattmannsdorfer represents the modern, strategic form of political influence:</p><ul><li><strong>Move of Succession:</strong> The nomination as deputy to Thomas Stelzer on March 23 is internally evaluated as &quot;Operation Crown Prince&quot;. It is the OÖVP&#39;s attempt to reposition itself personally before the Wöginger verdict on April 21 and to focus on &quot;economic competence&quot; and the &quot;future&quot;.</li><li><strong>From the Background to the Spotlight:</strong> While Wöginger is fighting for his reputation in the courtroom in Linz, Hattmannsdorfer is expanding his position as a strong link between Vienna and Linz.</li></ul><h2 id="forensic-note" tabindex="-1">Forensic Note: <a class="header-anchor" href="#forensic-note" aria-label="Permalink to &quot;Forensic Note:&quot;">​</a></h2><p>We are watching closely how Hattmannsdorfer manages the legacy of the Wöginger era. Will he continue the system of &quot;Hard Prose&quot; or clothe it in a new, smoother guise? In <strong>Part 4</strong> of our project, he will play a central role as a symbol of &quot;market consolidation&quot; within the party.</p><p>Traffic to the Hattmannsdorfer profile in our archive has jumped since noon today. The public is beginning to understand: <strong>After Wöginger comes not the vacuum, but the strategy.</strong></p>',11)])])}const u=t(a,[["render",s]]);export{d as __pageData,u as default};
